<?php
 namespace QQWorld\Framework\View\Test\Unit\Asset\PreProcessor; use QQWorld\Framework\View\Asset\Minification; use QQWorld\Framework\View\Asset\PreProcessor\MinificationFilenameResolver; class MinificationFilenameResolverTest extends \PHPUnit\Framework\TestCase { public function testResolve($isMin, $input, $expected) { $minificationMock = $this->getMockBuilder(Minification::class) ->disableOriginalConstructor() ->getMock(); $minificationMock->expects(self::once()) ->method('isEnabled') ->with('ext') ->willReturn($isMin); $resolver = new MinificationFilenameResolver($minificationMock); self::assertEquals($expected, $resolver->resolve($input)); } public function dataProviderForTestResolve() { return [ [ 'isMin' => true, 'input' => 'test.min.ext', 'expected' => 'test.ext' ], [ 'isMin' => false, 'input' => 'test.min.ext', 'expected' => 'test.min.ext' ], [ 'isMin' => false, 'input' => 'test.ext', 'expected' => 'test.ext' ] ]; } } 